using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Security.Cryptography;
namespace CodexLight.Bootstrap {
 [DataContract]internal sealed class ReceiptFileRecord{[DataMember(Order=0)]public string Path="";[DataMember(Order=1)]public long Size;[DataMember(Order=2)]public string Sha256="";}
 [DataContract]internal sealed class ReceiptRecord{[DataMember(Order=0)]public int Version=1;[DataMember(Order=1)]public string InstallId="";[DataMember(Order=2)]public string Target="";[DataMember(Order=3)]public List<ReceiptFileRecord> Files=new List<ReceiptFileRecord>();}
 internal static class UpgradeReceiptCodec {
  public const string Filename="CodexLight.install-receipt.json";
  static byte[] Serialize(ReceiptRecord value){using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(ReceiptRecord)).WriteObject(stream,value);return stream.ToArray();}}
  public static byte[] Encode(InstallReceipt receipt){receipt.Fingerprint();if(receipt.Files.Any(f=>string.Equals(f.Path,Filename,StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("Receipt cannot list itself");return Serialize(new ReceiptRecord{InstallId=receipt.InstallId,Target=receipt.Target,Files=receipt.Files.OrderBy(f=>f.Path,StringComparer.OrdinalIgnoreCase).Select(f=>new ReceiptFileRecord{Path=f.Path,Size=f.Size,Sha256=f.Sha256.ToLowerInvariant()}).ToList()});}
  public static InstallReceipt Decode(byte[] bytes,string expectedHash,string expectedTarget){if(bytes==null||bytes.Length>1024*1024)throw new InvalidOperationException("Receipt size invalid");ReceiptRecord record;using(var stream=new MemoryStream(bytes))record=(ReceiptRecord)new DataContractJsonSerializer(typeof(ReceiptRecord)).ReadObject(stream)!;if(record==null||record.Version!=1||record.Files==null||!Serialize(record).SequenceEqual(bytes))throw new InvalidOperationException("Receipt is not canonical or contains unknown fields");var receipt=new InstallReceipt(record.InstallId,record.Target,record.Files.Select(f=>new UpgradeFile(f.Path,f.Size,f.Sha256)));if(!string.Equals(receipt.Target,expectedTarget,StringComparison.OrdinalIgnoreCase)||!string.Equals(receipt.Fingerprint(),expectedHash,StringComparison.OrdinalIgnoreCase)||!Encode(receipt).SequenceEqual(bytes))throw new InvalidOperationException("Receipt ownership mismatch");return receipt;}
  public static InstallReceipt DecodeLegacyRepair(byte[] bytes,InstallReceipt exactEvidence){if(bytes==null||bytes.Length>1024*1024)throw new InvalidOperationException("Legacy receipt size invalid");ReceiptRecord record;using(var stream=new MemoryStream(bytes))record=(ReceiptRecord)new DataContractJsonSerializer(typeof(ReceiptRecord)).ReadObject(stream)!;if(record==null||record.Version!=1||record.Files==null||!Serialize(record).SequenceEqual(bytes))throw new InvalidOperationException("Legacy receipt format invalid");var receipt=new InstallReceipt(record.InstallId,record.Target,record.Files.Select(f=>new UpgradeFile(f.Path,f.Size,f.Sha256)));var expected=new InstallReceipt(receipt.InstallId,exactEvidence.Target,exactEvidence.Files);if(receipt.Fingerprint()!=expected.Fingerprint()||!Encode(receipt).SequenceEqual(bytes))throw new InvalidOperationException("Legacy receipt does not exactly match reviewed evidence");return receipt;}
  static UpgradeFile File(byte[] bytes){using(var sha=SHA256.Create())return new UpgradeFile(Filename,bytes.Length,BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant());}
  // Include the receipt in the SAME file transaction without making it self-referential.
  // Caller places Encode(nextReceipt) in the verified temporary payload source.
  public static UpgradePlan Attach(UpgradePlan plan,byte[] oldBytes,InstallReceipt nextReceipt){var old=Decode(oldBytes,plan.ReceiptHash,plan.Target);if(old.InstallId!=nextReceipt.InstallId||!string.Equals(nextReceipt.Target,plan.Target,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Receipt identity cannot change during upgrade");if(plan.Steps.Any(s=>string.Equals(s.Path,Filename,StringComparison.OrdinalIgnoreCase))||plan.PreservedUnknown.Contains(Filename,StringComparer.OrdinalIgnoreCase))throw new InvalidOperationException("Receipt path collision");var expected=plan.Steps.Where(s=>s.After!=null).Select(s=>s.After!).OrderBy(f=>f.Path,StringComparer.OrdinalIgnoreCase).ToList();var actual=nextReceipt.Files.OrderBy(f=>f.Path,StringComparer.OrdinalIgnoreCase).ToList();if(expected.Count!=actual.Count||expected.Where((f,i)=>f.Path!=actual[i].Path||f.Size!=actual[i].Size||!string.Equals(f.Sha256,actual[i].Sha256,StringComparison.OrdinalIgnoreCase)).Any())throw new InvalidOperationException("Next receipt does not describe the planned payload");var steps=plan.Steps.ToList();steps.Add(new UpgradeStep("replace",Filename,File(oldBytes),File(Encode(nextReceipt))));return new UpgradePlan(plan.Target,plan.ReceiptHash,steps,plan.PreservedUnknown.ToList());}
 }
}
